// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Recorder rec;

    function setUp() public { c = new airPort(); rec = new Recorder(); }

    // fuzzed params: from address, array of one recipient (we restrict to length 1 so we can reason about single call), value
    function testFuzz_property(address from, address tos0, uint256 v, bool calleeReverts) public {
        // keep tos0 non-zero to be an admissible address (but allow zero too); require _tos.length > 0 is enforced by C
        vm.assume(tos0 != address(0));
        // build single-element array
        address[] memory _tos = new address[](1);
        _tos[0] = tos0;

        // The Recorder can be toggled to optionally revert when called to exercise both success and failure paths
        rec.setShouldRevert(calleeReverts);

        // Call through c.transfer; capture whether it succeeded (reference always should succeed when selector matches)
        bool ok;
        try c.transfer(from, address(rec), _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always encodes selector of transferFrom(address,address,uint256)
        // so Recorder should have recorded exactly one call with that selector and decoded args matching (from, tos0, v)
        // When the callee reverts, the call into Recorder will revert and c.transfer should revert (ok==false).
        // The mutant changes the selector to a different signature; Recorder will then record a different selector
        // or fail to decode the expected args. We assert the universal property that when c.transfer returns
        // (ok==true) Recorder observed exactly one successful call whose decoded selector is transferFrom selector

        bytes4 expected = bytes4(keccak256("transferFrom(address,address,uint256)"));

        // If c.transfer succeeded then Recorder.mustHaveRecorded == true and recordedSelector must equal expected
        if (ok) {
            // read what Recorder recorded
            bytes4 sel = rec.lastSelector();
            address a0 = rec.lastArgAddr1();
            address a1 = rec.lastArgAddr2();
            uint256 a2 = rec.lastArgUint1();
            // single assertion that ties c's observable outcome (success) to the expected selector and args
            assertTrue(sel == expected && a0 == from && a1 == tos0 && a2 == v);
        } else {
            // if call reverted, then recorder either saw nothing or the call reverted; in the reference, this happens
            // only when the Recorder itself was set to revert. So ensure that when c.transfer reverted, the Recorder was
            // instructed to revert (i.e., calleeReverts==true). This is implied by the reference; mutant may revert
            // unexpectedly for some inputs.
            assertTrue(calleeReverts == true);
        }
    }
}

// Recorder contract: exposes the function with the exact signature transferFrom(address,address,uint256)
// so that well-formed calls decode into this function. It records selector and args. It can also be set to revert.
contract Recorder {
    bool public shouldRevert;
    bytes4 private _lastSelector;
    address private _lastAddr1;
    address private _lastAddr2;
    uint256 private _lastUint1;
    uint256 public calls;

    function setShouldRevert(bool r) public { shouldRevert = r; }

    // match the selector the reference uses
    function transferFrom(address a, address b, uint256 v) external returns (bool) {
        if (shouldRevert) revert("rec revert");
        _lastSelector = msg.sig;
        _lastAddr1 = a;
        _lastAddr2 = b;
        _lastUint1 = v;
        calls += 1;
        return true;
    }

    // fallback to catch mismatched selectors: record selector and raw data
    fallback() external payable {
        if (shouldRevert) revert("rec revert");
        _lastSelector = msg.sig;
        calls += 1;
        // leave args zeroed if cannot decode
    }

    function lastSelector() external view returns (bytes4) { return _lastSelector; }
    function lastArgAddr1() external view returns (address) { return _lastAddr1; }
    function lastArgAddr2() external view returns (address) { return _lastAddr2; }
    function lastArgUint1() external view returns (uint256) { return _lastUint1; }
}
